sys_script.script:
(function executeRule(current, previous) {

    var appointmentId = current.getUniqueValue();
    var invoiceId = '';

    // STEP 1: Check if Invoice already exists
    var invoice = new GlideRecord('x_2223823_apollo_0_invoice');

    invoice.addQuery('appointment', appointmentId);
    invoice.query();

    if (invoice.next()) {

        invoiceId = invoice.getUniqueValue();

    } else {

        // STEP 2: Create new Invoice
        invoice.initialize();

        invoice.setValue('appointment', appointmentId);
        invoice.setValue('patient', current.getValue('patient'));
        invoice.setValue('hospital', current.getValue('hospital'));

        invoice.setValue('patient_type', 'opd');

        invoice.setValue('total_amount', 0);
        invoice.setValue('paid_amount', 0);
        invoice.setValue('balance_amount', 0);

        invoice.setValue('status', 'draft');
        invoice.setValue('final_invoice', false);

        invoiceId = invoice.insert();
    }

    // STEP 3: Validate Invoice
    if (!invoiceId) {

        gs.error('Invoice creation failed for appointment: ' + appointmentId);
        return;
    }

    // STEP 4: Link Invoice with Appointment
    var appointment = new GlideRecord('x_2223823_apollo_0_appointment');

    if (appointment.get(appointmentId)) {

        appointment.setValue('invoice', invoiceId);
        appointment.update();
    }

    // STEP 5: Check for existing Consultation Charge
    var charge = new GlideRecord('x_2223823_apollo_0_charge_line');

    charge.addQuery('source_table', current.getTableName());
    charge.addQuery('source_record', appointmentId);
    charge.addQuery('charge_type', 'consultation');
    charge.query();

    if (charge.next()) {
        return;
    }

    // STEP 6: Fetch Doctor Consultation Fee
    var doctorFee = 0;

    var doctor = new GlideRecord('x_2223823_apollo_0_doctor');

    if (!doctor.get(current.getValue('doctor'))) {

        gs.error('Doctor not found for appointment: ' + appointmentId);
        return;
    }

    var mode = current.getDisplayValue('mode');

    if (mode == 'In-Person') {

        doctorFee = doctor.getValue('opd_fee');

    } else if (mode == 'Video') {

        doctorFee = doctor.getValue('video_fee');

    } else {

        gs.error('Invalid appointment mode: ' + mode);
        return;
    }

    // STEP 7: Create Consultation Charge Line
    charge.initialize();

    charge.setValue('hospital', current.getValue('hospital'));
    charge.setValue('patient', current.getValue('patient'));
    charge.setValue('invoice', invoiceId);

    // Fee from Doctor table
    charge.setValue('amount', doctorFee);

    charge.setValue('charge_type', 'consultation');
    charge.setValue('status', 'invoiced');

    charge.setValue('description', 'Consultation Charge');

    charge.setValue('source_table', current.getTableName());
    charge.setValue('source_record', appointmentId);

    var chargeId = charge.insert();

    if (!chargeId) {
        gs.error('Consultation charge creation failed for appointment: ' + appointmentId);
    }

})(current, previous);
